	// over the WebSocket (e2e.history_key_shared).
	RotateHistoryKey(context.Context, *RotateHistoryKeyRequest) (*RotateHistoryKeyResponse, error)
	// ListHistoryKeyShares returns the shares waiting for the caller's
	// device, oldest first (at most 100). Unacknowledged shares are deleted
	// after 30 days.
	ListHistoryKeyShares(context.Context, *ListHistoryKeySharesRequest) (*ListHistoryKeySharesResponse, error)
	// AckHistoryKeyShares deletes received shares of the caller's device (1
	// to 100 IDs); other IDs are ignored.
	AckHistoryKeyShares(context.Context, *AckHistoryKeySharesRequest) (*AckHistoryKeySharesResponse, error)
